for t in range(int(input())):
	(n, k) = [*map(int, input().split())]
	p = 1
	while p < 1e+16:
		p *= k
	a = [*map(int, input().split())]
	valid = True
	while valid:
		chk = False
		for i in range(len(a)):
			if a[i] >= p:
				if chk:
					valid = False
					break
				else:
					chk = True
					a[i] -= p
		if sum(a) == 0 or p == 1:
			valid = False
		p //= k
	print('NO' if sum(a) else 'YES')
